#!/usr/bin/env python3
"""make-g3-driver.py: write ozarchy-g3-campaign.sh from ozarchy-p4s0-campaign.sh (run with python3 -I).

Only the three CAMPAIGN-SPECIFIC blocks change: config, per-cell hard checks, preflight (with its helper
checks). Everything else is copied line for line from the p4s0 driver (the shared machinery).
"""

import sys

SRC = "/home/oz/bench-results-matched/ozarchy-p4s0-tools/ozarchy-p4s0-campaign.sh"
DST = "/home/oz/bench-results-matched/ozarchy-g3-tools/ozarchy-g3-campaign.sh"
NOTE = (
    "# ozarchy-g3 driver: generated by ozarchy-g3-tools/make-g3-driver.py from ozarchy-p4s0-campaign.sh; "
    "only the CAMPAIGN-SPECIFIC blocks differ."
)

CONFIG = r"""# >>> CAMPAIGN-SPECIFIC: config (ozarchy-g3, item 6 Gate 3 checkpoint, owner design 18c: four arms, 300 markets uniform,
# CLOID_SHARE=0, commit tail, 120 s SAT; one 60 s warm-up w0, then n=4 per arm in rotated balanced rounds: every round has every
# arm, and the order rotates so no arm is always first or last). Arms (spec arm names):
#   goff   G   = 199bdc97 node (glibc, as shipped) + bench backport 22d3cc03; ORACLE_FEED=0 (like-for-like base)
#   moff   M   = d3cba5e2 node (jemalloc compiled in); ORACLE_FEED=0 (like-for-like primary)
#   mon    M   = d3cba5e2 node; ORACLE_FEED=1, ORACLE_PRICE=30000 ORACLE_INTERVAL_MS=2000 ORACLE_WALK_BP=0 ("as shipped")
#   gjoff  GJ  = the G node behind the je wrapper $ST/g-je (system jemalloc 5.3.1 LD_PRELOADed, MALLOC_CONF unset); ORACLE_FEED=0
# The G arms run under the d3cba5e2 harness (run-cell.sh). $ST/gj-run is a symlink to $ST/g-je, so cell() finds the wrapper.
unset TORUS_MODEL_PROFILE CRASH_KILL_AT_S TORUS_ROCKSDB_WAL_COMPRESSION TORUS_ROCKSDB_APPEND_CF_CODEC TORUS_TRADE_HISTORY TORUS_ROCKSDB_MAX_TOTAL_WAL_MB TORUS_P3_PROTO TORUS_P3_PROTO_INTERVAL STATE_HASH_ACTIVATION KILL_SIG KILL_WAIT LD_PRELOAD MALLOC_CONF P3RSS_HEAP_PREFIX TORUS_CHECKPOINT_INTERVAL_MS CLOID_SHARE
unset TORUS_CHECKPOINT_MAX_BYTES TORUS_EXEC_PIPELINE TORUS_STATE_HASH_FAILSTOP TORUS_SHUTDOWN_TIMEOUT_SECS
CAMP=G3
BUDGET=900
FD_STOP=16384
R=/home/oz/bench-results-matched
REPO=/home/oz/projects/torus-economy/Torus-hyperBFT
DEVNET=/home/oz/torus-wsl-devnet
KNOB=TORUS_CHECKPOINT_INTERVAL_MS=15000   # name only (knobchk): no arm sets it; the 15 s role default is the shipped state
ENABLE_RE='item 6 Phase 3: coalesced state checkpoints ON'
PIPE_RE=${PIPE_RE:-bl2 exec pipeline ENABLED}
SHA_HARNESS=d3cba5e2837dea109acb4077f625b0991e0e1ac3
WT_H=/home/oz/projects/wt/g3s0-d3cba5e2
HARNESS=$WT_H/tools/matched-bench/run-cell.sh
DETACH=$WT_H/tools/matched-bench/campaign/detach.sh
TOOLS=$R/ozarchy-g3-tools/matched-bench
T=$R/ozarchy-14236fa-tools
T3=$R/ozarchy-p3s0r-tools
SIDE=$R/ozarchy-p4s0-tools/perf-sidecar.sh
PYCHK=$R/ozarchy-acc-codec-check.py
LSM=$R/ozarchy-acc3-tools/ozarchy-acc3-lsm.py
RSTPY=$R/ozarchy-acc3-tools/ozarchy-acc3-restart.py
POST=$R/ozarchy-p3s2g-tools/ozarchy-p3c1-post.py
ST=${ST:-$R/ozarchy-g3s0-stage}
MD5_BUILD=${MD5_BUILD:-$R/ozarchy-g3s0-build/md5s.txt}
JEMALLOC=/usr/lib/libjemalloc.so.2
MK=300
METS=(9161 9162 9163)
CRASHCELL=0
G_SHA=199bdc9720468ca3c59aac29480882e5092b7796
GB_SHA=22d3cc03f540ed61f5b6930d56834112db84b284
# binary keys: g = G node 199bdc97 (glibc) + bench 22d3cc03 backport; gj = the same node and bench behind the je wrapper
# ($ST/gj-run -> $ST/g-je); m = d3cba5e2 node (jemalloc compiled in) + bench d3cba5e2
declare -A BSHA BWT BMD5 BBMD5
BSHA[g]=$G_SHA; BWT[g]=/home/oz/projects/wt/g3-bench-199bdc97
BSHA[gj]=$G_SHA; BWT[gj]=/home/oz/projects/wt/g3-bench-199bdc97
BSHA[m]=d3cba5e2837dea109acb4077f625b0991e0e1ac3; BWT[m]=$WT_H
BMD5[g]=$(awk '$1=="G" && $2=="199bdc97" {print $3}' "$MD5_BUILD" 2>/dev/null | tail -1)
BBMD5[g]=$(awk '$1=="bench-bG" && index($2,"22d3cc03")==1 {print $3}' "$MD5_BUILD" 2>/dev/null | tail -1)
BMD5[gj]=${BMD5[g]}; BBMD5[gj]=${BBMD5[g]}
BMD5[m]=$(awk '$1=="M" && $2=="d3cba5e2" {print $3}' "$MD5_BUILD" 2>/dev/null | tail -1)
BBMD5[m]=$(awk '$1=="bench-M" && $2=="d3cba5e2" {print $3}' "$MD5_BUILD" 2>/dev/null | tail -1)
# EXTRA_ENV knobs: the same empty-knob list as ozarchy-p4s0 (node-local knobs; empty on every arm)
KNOBS="TORUS_ROCKSDB_PIPELINED_WRITE= TORUS_RESIDENT_BOOKS= TORUS_NATIVE_ROOT_CACHE= TORUS_PARALLEL_SETTLE= TORUS_PARALLEL_BUCKET_HASH= TORUS_BUCKET_MEMBER_CACHE_MB= TORUS_BOOK_ROWS="
# arms: ABIN binary key, ATAIL commit, AKNOB 0 (no checkpoint knob), APROF none|je, ACLOID 0, AORC oracle feed 0|1
declare -A ABIN ATAIL AKNOB APROF KNOBX WALCAP ACLOID AORC
arm() { ABIN[$1]=$2; ATAIL[$1]=$3; AKNOB[$1]=$4; APROF[$1]=$5; ACLOID[$1]=$6; AORC[$1]=$7; }
arm goff g commit 0 none 0 0
arm moff m commit 0 none 0 0
arm mon m commit 0 none 0 1
arm gjoff gj commit 0 je 0 0
DD=$DEVNET
KNOBX[tw]=""; WALCAP[tw]=2147483648
export XDG_RUNTIME_DIR=${XDG_RUNTIME_DIR:-/run/user/$(id -u)}
RUN=$R/ozarchy-g3-run; P=ozarchy-g3-300m
# tag:arm:dur:kind:killat. Order: warm-up w0, then four rotated rounds (every arm once per round; first and last positions rotate).
CELLS=( "w0:moff:60:none:"
        "r1-goff:goff:120:none:" "r1-moff:moff:120:none:" "r1-mon:mon:120:none:" "r1-gjoff:gjoff:120:none:"
        "r2-moff:moff:120:none:" "r2-mon:mon:120:none:" "r2-gjoff:gjoff:120:none:" "r2-goff:goff:120:none:"
        "r3-mon:mon:120:none:" "r3-gjoff:gjoff:120:none:" "r3-goff:goff:120:none:" "r3-moff:moff:120:none:"
        "r4-gjoff:gjoff:120:none:" "r4-goff:goff:120:none:" "r4-moff:moff:120:none:" "r4-mon:mon:120:none:" )
# SMOKE=1: one 60 s cell per arm (the Step A gate: boot, sync, blocks, agreement and every per-cell check on all four arms)
if [ "${SMOKE:-0}" = 1 ]; then P=ozarchy-g3-smoke-300m; RUN=$RUN/smoke; CELLS=("s0-goff:goff:60:none:" "s0-moff:moff:60:none:" "s0-gjoff:gjoff:60:none:" "s0-mon:mon:60:none:"); fi
ANALYST=$R/ozarchy-g3-tools/analyst
export CELL_STEP_ANALYSIS_CMD="python3 -I $ANALYST/a-cells.py {out} {prefix} {tag}:{arm}"
export CELL_STEP_ANALYSIS_METRIC=ms
export CELL_STEP_TIMEOUT=${CELL_STEP_TIMEOUT:-900} CELL_STEP_ANALYSIS_TIMEOUT=${CELL_STEP_ANALYSIS_TIMEOUT:-600}
# <<< CAMPAIGN-SPECIFIC: config"""

HARD = r"""    # >>> CAMPAIGN-SPECIFIC: per-cell hard checks (a CHECK FAIL stops the campaign after the cell's row is written)
    [ -n "$SP" ] && { wait "$SP" 2>/dev/null; SP=; }
    if [ -s "$R/$label/node-environ-trie.txt" ]; then
        [ "$(grep -c "exe_md5=$nm" "$R/$label/node-environ-trie.txt")" = 3 ] || { echo "CHECK FAIL $label: node exe md5 != $nm"; return 1; }
        envok "$label" tw || return 1
        knobok "$label" tw "$R/$label/node-env-all.txt" 3 || return 1
        knobchk "$label" "$arm" "$R/$label/node-env-all.txt" 3 || return 1
        oraclechk "$label" "$arm" || return 1
        enablechk_g3 "$label" "$arm" || return 1
        ckptchk_g3 "$label" "$arm" || return 1
        statechk "$label" "$arm" || return 1
        fschk "$label" "$arm" || return 1
        tailchk "$label" "$tail" || return 1
        heapchk "$label" "$arm" || return 1
        cloidchk_g3 "$label" "$arm" || return 1
        n=$(grep -c ' TORUS_SHUTDOWN_TIMEOUT_SECS=' "$R/$label/node-env-all.txt"); [ "$n" = 0 ] || { echo "CHECK FAIL $label: TORUS_SHUTDOWN_TIMEOUT_SECS set on $n nodes (want the default 60)"; return 1; }
        echo "CHECK OK $label TORUS_SHUTDOWN_TIMEOUT_SECS unset on 3 nodes (node default 60 s)"
    else
        echo "CHECK FAIL $label: no node-environ-trie.txt"; return 1
    fi
    # <<< CAMPAIGN-SPECIFIC: per-cell hard checks"""

PRE_START = "# >>> CAMPAIGN-SPECIFIC: preflight (binaries G / GJ / M, harness and tools copy; helper checks)"

PRE_BODY = r"""enablechk_g3() { # label arm: the M arms (checkpoint enable line on every validator, on by default): enablechk_m. The pre-item-6
    # G arms (goff, gjoff: the 199bdc97 node has no checkpoint code): no enable line on any validator
    local label=$1 arm=$2 o=$R/$1 v n tot=""
    if [ "${ABIN[$arm]}" = m ]; then enablechk_m "$label" "$arm"; return; fi
    for v in 0 1 2; do
        n=$(zcat "$o/val$v.log.gz" | sed 's/\x1b\[[0-9;]*m//g' | grep -c -E "$ENABLE_RE")
        [ "$n" = 0 ] || { echo "CHECK FAIL $label: val$v shows the checkpoint enable line ($n) on pre-item-6 arm $arm"; return 1; }
        tot="$tot val$v=$n"
    done
    echo "CHECK OK $label checkpoint enable line absent (pre-item-6 arm $arm:$tot)"
}
ckptchk_g3() { # label arm: the M arms: ckptchk_m. The pre-item-6 G arms: no torus_exec_checkpoints series on any validator
    local label=$1 arm=$2 o=$R/$1 v a tot=""
    if [ "${ABIN[$arm]}" = m ]; then ckptchk_m "$label" "$arm"; return; fi
    for v in 0 1 2; do
        a=$(ckval "$o/metrics-after-val$v.txt")
        [ "$a" = absent ] || [ "$a" = 0 ] || { echo "CHECK FAIL $label: val$v torus_exec_checkpoints=$a on pre-item-6 arm $arm"; return 1; }
        tot="$tot val$v=$a"
    done
    echo "CHECK OK $label checkpoints (pre-item-6 arm $arm: no torus_exec_checkpoints series:$tot)"
}
cloidchk_g3() { # label arm: the M arms: cloidchk (summary ingest.cloids share 0, stamped 0, no duplicate_cloid). The G arms: the 22d3cc03
    # bench backport does not stamp cloids and prints no "Cloids (load-gen generated)" line, so summary.json has no ingest.cloids there.
    # Checked instead: --cloid-share 0 reached the bench (run.log cloid_share and bench cmd), bench.log has no cloid line, and no node
    # reports duplicate_cloid rejects (absent on the pre-item-6 nodes, or 0 on all 3).
    local label=$1 arm=$2 o=$R/$1 pc v d tot=""
    if [ "${ABIN[$arm]}" = m ]; then cloidchk "$label" "$arm"; return; fi
    pc=${ACLOID[$arm]}
    grep -q "cloid_share='$pc'" "$o/run.log" || { echo "CHECK FAIL $label: run.log has no cloid_share='$pc'"; return 1; }
    grep -q -- "--cloid-share $pc" "$o/run.log" || { echo "CHECK FAIL $label: bench cmd lacks --cloid-share $pc"; return 1; }
    if grep -q 'Cloids (load-gen generated)' "$o/bench.log" 2>/dev/null; then echo "CHECK FAIL $label: bench.log has a cloid line on the G backport (share $pc expected none)"; return 1; fi
    for v in 0 1 2; do
        [ -s "$o/metrics-after-val$v.txt" ] || { echo "CHECK FAIL $label: no metrics-after-val$v.txt"; return 1; }
        d=$(awk '$1 ~ /^torus_orders_rejected_reason_total\{.*reason="duplicate_cloid"/ {s+=$2; f=1} END{if (f) printf "%d", s; else print "absent"}' "$o/metrics-after-val$v.txt")
        [ "$d" = absent ] || [ "$d" = 0 ] || { echo "CHECK FAIL $label: val$v duplicate_cloid rejects = $d"; return 1; }
        tot="$tot val$v=$d"
    done
    echo "CHECK OK $label cloids (arm $arm, G backport: --cloid-share $pc on the bench cmd, no cloid line, duplicate_cloid:$tot)"
}
# preflight (binaries, harness and tools copy)
for b in g gj m; do
    [[ "${BMD5[$b]}" =~ ^[0-9a-f]{32}$ ]] || PF "no node md5 for key $b in $MD5_BUILD"
    [[ "${BBMD5[$b]}" =~ ^[0-9a-f]{32}$ ]] || PF "no bench md5 for key $b in $MD5_BUILD"
done
[ "$(git -C "${BWT[g]}" rev-parse HEAD)" = "$GB_SHA" ] && [ -z "$(git -C "${BWT[g]}" status --porcelain)" ] || PF "${BWT[g]} not clean at $GB_SHA (G bench backport)"
[ "$(md5sum < "$ST/g-run/release/torus-node" | cut -c1-32)" = "${BMD5[g]}" ] || PF "$ST/g-run torus-node md5 is not ${BMD5[g]}"
[ "$(md5sum < "$ST/g-run/release/bench-throughput" | cut -c1-32)" = "${BBMD5[g]}" ] || PF "$ST/g-run bench md5 is not ${BBMD5[g]}"
n=$(nm "$ST/g-run/release/torus-node" 2>/dev/null | grep -c '_rjem_'); [ "$n" = 0 ] || PF "G node has $n _rjem_ symbols (expected the glibc build)"
[ -f "$JEMALLOC" ] || PF "$JEMALLOC missing"
[ "$(readlink -f "$ST/gj-run")" = "$ST/g-je" ] || PF "$ST/gj-run must link to $ST/g-je (cell() reads \$ST/\$b-run)"
grep -qxF "exec $ST/g-run/release/torus-node \"\$@\"" "$ST/g-je/release/torus-node" || PF "$ST/g-je wrapper does not exec the G node"
grep -qxF "export LD_PRELOAD=$JEMALLOC" "$ST/g-je/release/torus-node" || PF "$ST/g-je wrapper lacks the jemalloc preload"
! grep -q '^export MALLOC_CONF' "$ST/g-je/release/torus-node" || PF "$ST/g-je wrapper sets MALLOC_CONF"
[ "$(md5sum < "$ST/g-je/release/bench-throughput" | cut -c1-32)" = "${BBMD5[gj]}" ] || PF "$ST/g-je bench md5 is not ${BBMD5[gj]}"
[ "$(md5sum < "$ST/m-run/release/torus-node" | cut -c1-32)" = "${BMD5[m]}" ] || PF "$ST/m-run torus-node md5 is not ${BMD5[m]}"
[ "$(md5sum < "$ST/m-run/release/bench-throughput" | cut -c1-32)" = "${BBMD5[m]}" ] || PF "$ST/m-run bench md5 is not ${BBMD5[m]}"
nm_m=$(nm "$ST/m-run/release/torus-node" 2>/dev/null | grep -c '_rjem_'); [ "$nm_m" -gt 0 ] || PF "M node has no _rjem_ symbols (jemalloc compiled in expected)"
echo "[$(date +%T)] G node ${BMD5[g]:0:8} (no _rjem_), G bench ${BBMD5[g]:0:8}; GJ wrapper $(md5sum < "$ST/g-je/release/torus-node" | cut -c1-8) execs the G node; M node ${BMD5[m]:0:8} _rjem_ symbols: $nm_m; M bench ${BBMD5[m]:0:8}"
[ "$(git -C "$WT_H" rev-parse HEAD)" = "$SHA_HARNESS" ] || PF "harness worktree is not at $SHA_HARNESS"
grep -q 'CLOID_SHARE' "$HARNESS" || PF "$HARNESS does not know CLOID_SHARE"
grep -q 'IN_FLIGHT_TAIL' "$HARNESS" || PF "$HARNESS does not know IN_FLIGHT_TAIL"
grep -q 'cloid-share' "$TOOLS/summarize.py" || PF "harness summarize.py lacks ingest.cloids"
grep -q 'checkpoint_deferred_join' "$TOOLS/summarize.py" || PF "harness summarize.py lacks checkpoint_deferred_join"
[ "$(diff -rq -x __pycache__ "$WT_H/tools/matched-bench" "$TOOLS" | wc -l)" = 0 ] || PF "tools copy differs from $WT_H"
[ -f "$POST" ] || PF "$POST missing"
command -v jq > /dev/null || PF "jq missing"
{ [ "$(git -C "$WT_H" rev-parse HEAD)" = "$SHA_HARNESS" ] && [ -z "$(git -C "$WT_H" status --porcelain)" ]; } || PF "$WT_H not clean at $SHA_HARNESS"
[ "$(stat -f -c %T "$DEVNET")" = btrfs ] || PF "$DEVNET is not on btrfs (shared NVMe)"
[ "$(awk '/^MemAvailable:/{print $2}' /proc/meminfo)" -ge 40000000 ] || PF "MemAvailable < 40 GB"
for f in "$PYCHK" "$LSM" "$RSTPY" "$TOOLS/crash-freeze.py" "$HARNESS" "$DETACH" "$T/task-sampler.py" "$T/positions.py" "$SIDE"; do [ -f "$f" ] || PF "$f missing"; done
for f in "$HARNESS" "$DETACH" "$TOOLS/crash-kill.sh" "$T/cpu-sampler.sh" "$T3/io-sampler.sh" "$SIDE"; do [ -x "$f" ] || PF "$f not executable"; done"""

PRE_END = "# <<< CAMPAIGN-SPECIFIC: preflight"


def find(lines, pred, what):
    hits = [i for i, l in enumerate(lines) if pred(l)]
    if len(hits) != 1:
        sys.exit("make-g3-driver: %s matched %d lines (want 1)" % (what, len(hits)))
    return hits[0]


def main():
    lines = open(SRC, encoding="utf-8").read().split("\n")
    c0 = find(
        lines, lambda l: l.startswith("# >>> CAMPAIGN-SPECIFIC: config"), "config start"
    )
    c1 = find(lines, lambda l: l == "# <<< CAMPAIGN-SPECIFIC: config", "config end")
    h0 = find(
        lines,
        lambda l: l.strip().startswith("# >>> CAMPAIGN-SPECIFIC: per-cell hard checks"),
        "hard start",
    )
    h1 = find(
        lines,
        lambda l: l.strip() == "# <<< CAMPAIGN-SPECIFIC: per-cell hard checks",
        "hard end",
    )
    p0 = find(
        lines,
        lambda l: l.startswith("# >>> CAMPAIGN-SPECIFIC: preflight"),
        "preflight start",
    )
    p1 = find(
        lines, lambda l: l == "# <<< CAMPAIGN-SPECIFIC: preflight", "preflight end"
    )
    oc = find(lines, lambda l: l.startswith("oraclechk() {"), "oraclechk helper")
    hp = find(
        lines,
        lambda l: l.startswith("# preflight (binary, harness and tools copy)"),
        "old preflight line",
    )
    if not (c0 < c1 < h0 < h1 < p0 < oc < hp < p1):
        sys.exit("make-g3-driver: CAMPAIGN-SPECIFIC blocks out of order")
    helpers = lines[
        oc:hp
    ]  # oraclechk, enablechk_m, ckptchk_m (p4s0 helpers, kept verbatim)
    out = [lines[0], NOTE] + lines[1:c0]
    out += CONFIG.split("\n")
    out += lines[c1 + 1 : h0]
    out += HARD.split("\n")
    out += lines[h1 + 1 : p0]
    out += [PRE_START] + helpers + PRE_BODY.split("\n") + [PRE_END]
    out += lines[p1 + 1 :]
    text = "\n".join(out)
    with open(DST, "w", encoding="utf-8") as fh:
        fh.write(text)
    print("wrote %s (%d lines; helpers kept: %d)" % (DST, len(out), len(helpers)))


if __name__ == "__main__":
    main()
